#include <stdio.h>
#include <stdlib.h>

static int compare_ints(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int n, costs[3];

    if (scanf("%d%d%d%d", &n, &costs[0], &costs[1], &costs[2]) != 4) {
        return 0;
    }

    qsort(costs, 3, sizeof(int), compare_ints);

    int count = 0;
    for (int i = 0; i < 3 && n >= costs[i]; i++) {
        n -= costs[i];
        count++;
    }

    printf("%d\n", count);
    return 0;
}
